    (kentik_snmp_ifHCInOctets{snmp_group=~"$snmp_group",device_name=~"$instance", if_interface_name=~"$interface_name"})
  ) * 8 / 60
) or (
  max by(if_interface_name) (kentik_snmp_if_OperStatus{snmp_group=~"$snmp_group",device_name=~"$instance", if_interface_name=~"$interface_name"}) * 0
)

(
  sum by(if_interface_name) (
    (kentik_snmp_ifHCOutOctets{snmp_group=~"$snmp_group",device_name=~"$instance", if_interface_name=~"$interface_name"})
  ) * 8 / 60
) or (
  max by(if_interface_name) (kentik_snmp_if_OperStatus{snmp_group=~"$snmp_group",device_name=~"$instance", if_interface_name=~"$interface_name"}) * 0
)

(
  max by(if_interface_name) (kentik_snmp_IfInUtilization{snmp_group=~"$snmp_group",device_name=~"$instance", if_interface_name=~"$interface_name"})
) or (
  max by(if_interface_name) (kentik_snmp_if_OperStatus{snmp_group=~"$snmp_group",device_name=~"$instance", if_interface_name=~"$interface_name"}) * 0
)

(
  max by(if_interface_name) (kentik_snmp_IfOutUtilization{snmp_group=~"$snmp_group",device_name=~"$instance", if_interface_name=~"$interface_name"})
) or (
  max by(if_interface_name) (kentik_snmp_if_OperStatus{snmp_group=~"$snmp_group",device_name=~"$instance", if_interface_name=~"$interface_name"}) * 0
)

