  kentik_snmp_if_OperStatus{snmp_group=~"$snmp_group",device_name=~"$instance", if_interface_name=~"$interface_name"}
)
and on(if_interface_name)
(
  changes(
    max by(if_interface_name)(kentik_snmp_if_OperStatus{snmp_group=~"$snmp_group",device_name=~"$instance"})[$__range:1m]
